-- ==============================================================================
-- My Student Club - CA / CS / CMA: course eligibility tags on job tables
-- ==============================================================================
-- GENERATED by scripts/courses/build-pages.js from scripts/courses/courses.js.
-- Do not edit by hand; change courses.js and run: npm run build:pages
--
-- What it does (safe to re-run):
--   1. Adds eligible_courses text[] (default {CA}) and eligible_courses_manual
--      boolean to the four job tables.
--   2. Creates msc_detect_courses(description), which tags CS / CMA using the
--      same patterns the portal uses today.
--   3. Adds a trigger that tags new and edited vacancies automatically, unless
--      an admin has set eligible_courses by hand (eligible_courses_manual = true).
--   4. Backfills the last 90 days, adds GIN indexes and lets the website read
--      the new column.
--
-- Until this runs, the CS and CMA lanes still work: they match the same
-- patterns against Description on the fly. Afterwards every lane switches to
-- the indexed column automatically (faster, and admins can correct tags);
-- CA lanes then show rows tagged CA, which every row is unless an admin
-- marks it CS- or CMA-only.
--
-- Before running: step 4 UPDATEs recent rows. If these tables have UPDATE
-- triggers or webhooks (for example push notifications), check they ignore
-- changes to eligible_courses.
--
-- Posting a CS- or CMA-only vacancy later: insert it with
--   eligible_courses = '{CS}' (or '{CMA}') and eligible_courses_manual = true.
-- ==============================================================================

BEGIN;

-- 1. Columns ---------------------------------------------------------------------
ALTER TABLE IF EXISTS public."Industrial Training Job Portal"
    ADD COLUMN IF NOT EXISTS eligible_courses text[] NOT NULL DEFAULT '{CA}',
    ADD COLUMN IF NOT EXISTS eligible_courses_manual boolean NOT NULL DEFAULT false;
ALTER TABLE IF EXISTS public."Articleship Jobs"
    ADD COLUMN IF NOT EXISTS eligible_courses text[] NOT NULL DEFAULT '{CA}',
    ADD COLUMN IF NOT EXISTS eligible_courses_manual boolean NOT NULL DEFAULT false;
ALTER TABLE IF EXISTS public."Semi Qualified Jobs"
    ADD COLUMN IF NOT EXISTS eligible_courses text[] NOT NULL DEFAULT '{CA}',
    ADD COLUMN IF NOT EXISTS eligible_courses_manual boolean NOT NULL DEFAULT false;
ALTER TABLE IF EXISTS public."Fresher Jobs"
    ADD COLUMN IF NOT EXISTS eligible_courses text[] NOT NULL DEFAULT '{CA}',
    ADD COLUMN IF NOT EXISTS eligible_courses_manual boolean NOT NULL DEFAULT false;

-- 2. Classifier --------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.msc_detect_courses(description text)
RETURNS text[]
LANGUAGE sql
IMMUTABLE
SET search_path = pg_catalog, public
AS $fn$
    SELECT array_remove(ARRAY[
        'CA',
        CASE WHEN coalesce(description, '') ~* $re$(\mcs\M|company\s+secretar|icsi|\macs\M)$re$
              AND coalesce(description, '') ~* $re$((\mca|\mcma|\micwai?|\mcwa|\mmba|\mllb|\mcfa|\mcpa|\macca|\mcia|\mm\.?\s?com|\mb\.?\s?com|\mbba|\mbaf|\mgraduates?|\minter|\mipcc|\mfrm)\M\s*\)?\s*(,\s*or\s|,\s*and\s|/|,|&|\||\sor\s|\sand\s|and\s*/\s*or)\s*(semi[\s-]*qualified\s+)?\ma?cs\M(?!\s*(firms?|partners|consultants)\M)|\ma?cs\M(?!\s*(firms?|partners|consultants)\M)\s*(\(\s*[a-z]+\s*\))?\s*(/|,|&|\||\sor\s|\sand\s)\s*(ca|cma|icwai?|cwa|mba|llb|law|cfa|cpa|acca|m\.?\s?com|b\.?\s?com)\M|\ma?cs\M(?!\s*(firms?|partners|consultants)\M)\s*[-–(]?\s*(executive|professional|inter|intermediate|final|foundation|qualified|semi|trainee|student|aspirant|fresher|dropout|drop\s*out|article|pursuing|cleared|appeared|member|candidate|course)|(qualified|pursuing|\minter|fresher|aspiring)\s+(ca\s*/\s*)?\ma?cs\M(?!\s*(firms?|partners|consultants)\M)|(qualified|fresher|practi[sc]ing|aspiring|trainee)\s+(ca\s*/\s*)?company\s+secretar|company\s+secretar(y|ies)\s*[-–(:]*\s*(trainee|fresher|intern|executive|professional|cs\M|qualified|\d)|(accountant|\mca|\mcma|\micwa)\M\s*(\([a-z]+\))?\s*(/|,|\sor\s)\s*(cost\s*(&|and)?\s*(management|works)?\s*accountant\s*(/|,|\sor\s)\s*)?company\s+secretary\M|(hiring|looking\s+for|inviting|applications\s+from|openings?\s+for)[a-z\s-]*company\s+secretar|\micsi\M(?!\s+invoic))$re$
              AND coalesce(description, '') !~* $re$(not\s+eligible[^.\n]*\ma?cs\M|((\mca\M|chartered\s+accountant)[^.\n•]*(mandatory|required|is\s+a\s+must)|must\s+be\s+(an?\s+)?(qualified\s+)?(\mca\M|chartered\s+accountant))[^.\n•]*\ma?cs\M[^.\n•]*(advantage|plus|preferable|good\s+to\s+have|in\s+addition)|\mca\s*\+\s*cs\M|required:?\s*(qualified\s+)?ca\s*(&|and)\s*cs\M)$re$
             THEN 'CS' END,
        CASE WHEN coalesce(description, '') ~* $re$(\mcmas?\M|icwa|\mcwa\M|icmai?|cost\s*(and|&)?\s*(management|works)?\s*accountan|\macma\M)$re$
              AND coalesce(description, '') ~* $re$((?<!us\s)\mcmas?\M(?!\s*[-–:(]?\s*(data|prep|report|credit|statement|projection|format|study|working|project\s+fin|\(?\s*(us|usa|u\.s|ima)\M))|\micwai?s?\M|\maicwa|\mcwa\M|\micmai?\M|cost\s*(and|&)?\s*(management|works)?\s*accountan|\macma\M)$re$
              AND coalesce(description, '') !~* $re$(not\s+eligible[^.\n]*(\mcma\M|icwa)|\mcma\M[^.\n]*(not\s+eligible|should\s+not\s+apply|need\s+not\s+apply)|\mno\s+cma\M|❌[^.\n]*\mcma\M|((\mca\M|chartered\s+accountant)[^.\n•]*(mandatory|required|is\s+a\s+must)|must\s+be\s+(an?\s+)?(qualified\s+)?(\mca\M|chartered\s+accountant))[^.\n•]*(\mcma\M|icwa)[^.\n•]*(advantage|plus|preferable|good\s+to\s+have|in\s+addition)|\mus\s+cpa\s*/\s*cma\M|certified\s+management\s+accountant|\mcgma\M)$re$
             THEN 'CMA' END
    ], NULL);
$fn$;

-- 3. Auto-tag trigger ------------------------------------------------------------------
-- SECURITY DEFINER so the trigger can call the detector even though website
-- roles may not (see the REVOKE below), whoever inserts the row.
CREATE OR REPLACE FUNCTION public.msc_tag_eligible_courses()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $fn$
BEGIN
    IF NOT coalesce(NEW.eligible_courses_manual, false) THEN
        NEW.eligible_courses := public.msc_detect_courses(NEW."Description");
    END IF;
    RETURN NEW;
END;
$fn$;

DROP TRIGGER IF EXISTS msc_tag_eligible_courses ON public."Industrial Training Job Portal";
CREATE TRIGGER msc_tag_eligible_courses
    BEFORE INSERT OR UPDATE OF "Description", eligible_courses_manual ON public."Industrial Training Job Portal"
    FOR EACH ROW EXECUTE FUNCTION public.msc_tag_eligible_courses();
DROP TRIGGER IF EXISTS msc_tag_eligible_courses ON public."Articleship Jobs";
CREATE TRIGGER msc_tag_eligible_courses
    BEFORE INSERT OR UPDATE OF "Description", eligible_courses_manual ON public."Articleship Jobs"
    FOR EACH ROW EXECUTE FUNCTION public.msc_tag_eligible_courses();
DROP TRIGGER IF EXISTS msc_tag_eligible_courses ON public."Semi Qualified Jobs";
CREATE TRIGGER msc_tag_eligible_courses
    BEFORE INSERT OR UPDATE OF "Description", eligible_courses_manual ON public."Semi Qualified Jobs"
    FOR EACH ROW EXECUTE FUNCTION public.msc_tag_eligible_courses();
DROP TRIGGER IF EXISTS msc_tag_eligible_courses ON public."Fresher Jobs";
CREATE TRIGGER msc_tag_eligible_courses
    BEFORE INSERT OR UPDATE OF "Description", eligible_courses_manual ON public."Fresher Jobs"
    FOR EACH ROW EXECUTE FUNCTION public.msc_tag_eligible_courses();

-- Keep both functions out of the public API (/rest/v1/rpc).
REVOKE EXECUTE ON FUNCTION public.msc_detect_courses(text) FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.msc_tag_eligible_courses() FROM PUBLIC, anon, authenticated;

-- 4. Backfill recent rows, index, and allow the website to read the column ---------
UPDATE public."Industrial Training Job Portal"
    SET eligible_courses = public.msc_detect_courses("Description")
    WHERE NOT eligible_courses_manual
      AND "Created_At" >= now() - interval '90 days'
      AND eligible_courses IS DISTINCT FROM public.msc_detect_courses("Description");
CREATE INDEX IF NOT EXISTS "industrial_training_job_portal_eligible_courses_idx"
    ON public."Industrial Training Job Portal" USING gin (eligible_courses);
GRANT SELECT (eligible_courses) ON public."Industrial Training Job Portal" TO anon, authenticated;
UPDATE public."Articleship Jobs"
    SET eligible_courses = public.msc_detect_courses("Description")
    WHERE NOT eligible_courses_manual
      AND "Created_At" >= now() - interval '90 days'
      AND eligible_courses IS DISTINCT FROM public.msc_detect_courses("Description");
CREATE INDEX IF NOT EXISTS "articleship_jobs_eligible_courses_idx"
    ON public."Articleship Jobs" USING gin (eligible_courses);
GRANT SELECT (eligible_courses) ON public."Articleship Jobs" TO anon, authenticated;
UPDATE public."Semi Qualified Jobs"
    SET eligible_courses = public.msc_detect_courses("Description")
    WHERE NOT eligible_courses_manual
      AND "Created_At" >= now() - interval '90 days'
      AND eligible_courses IS DISTINCT FROM public.msc_detect_courses("Description");
CREATE INDEX IF NOT EXISTS "semi_qualified_jobs_eligible_courses_idx"
    ON public."Semi Qualified Jobs" USING gin (eligible_courses);
GRANT SELECT (eligible_courses) ON public."Semi Qualified Jobs" TO anon, authenticated;
UPDATE public."Fresher Jobs"
    SET eligible_courses = public.msc_detect_courses("Description")
    WHERE NOT eligible_courses_manual
      AND "Created_At" >= now() - interval '90 days'
      AND eligible_courses IS DISTINCT FROM public.msc_detect_courses("Description");
CREATE INDEX IF NOT EXISTS "fresher_jobs_eligible_courses_idx"
    ON public."Fresher Jobs" USING gin (eligible_courses);
GRANT SELECT (eligible_courses) ON public."Fresher Jobs" TO anon, authenticated;

-- 5. Check the result before committing ----------------------------------------------
SELECT 'Industrial Training Job Portal' AS job_table,
       count(*) FILTER (WHERE 'CS' = ANY (eligible_courses)) AS cs_listings,
       count(*) FILTER (WHERE 'CMA' = ANY (eligible_courses)) AS cma_listings
FROM public."Industrial Training Job Portal"
WHERE "Created_At" >= now() - interval '30 days'
UNION ALL
SELECT 'Articleship Jobs' AS job_table,
       count(*) FILTER (WHERE 'CS' = ANY (eligible_courses)) AS cs_listings,
       count(*) FILTER (WHERE 'CMA' = ANY (eligible_courses)) AS cma_listings
FROM public."Articleship Jobs"
WHERE "Created_At" >= now() - interval '30 days'
UNION ALL
SELECT 'Semi Qualified Jobs' AS job_table,
       count(*) FILTER (WHERE 'CS' = ANY (eligible_courses)) AS cs_listings,
       count(*) FILTER (WHERE 'CMA' = ANY (eligible_courses)) AS cma_listings
FROM public."Semi Qualified Jobs"
WHERE "Created_At" >= now() - interval '30 days'
UNION ALL
SELECT 'Fresher Jobs' AS job_table,
       count(*) FILTER (WHERE 'CS' = ANY (eligible_courses)) AS cs_listings,
       count(*) FILTER (WHERE 'CMA' = ANY (eligible_courses)) AS cma_listings
FROM public."Fresher Jobs"
WHERE "Created_At" >= now() - interval '30 days';

COMMIT;
